/**
 * Summary of an AI Agent task exported via UniFFI.
 */
public struct AgentTaskStatus {
    public var taskId: UInt64
    public var prompt: String
    public var state: String
    public var verificationPassed: Bool
    public var unifiedDiffPreview: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(taskId: UInt64, prompt: String, state: String, verificationPassed: Bool, unifiedDiffPreview: String?) {
        self.taskId = taskId
        self.prompt = prompt
        self.state = state
        self.verificationPassed = verificationPassed
        self.unifiedDiffPreview = unifiedDiffPreview
    }
}



extension AgentTaskStatus: Equatable, Hashable {
    public static func ==(lhs: AgentTaskStatus, rhs: AgentTaskStatus) -> Bool {
        if lhs.taskId != rhs.taskId {
            return false
        }
        if lhs.prompt != rhs.prompt {
            return false
        }
        if lhs.state != rhs.state {
            return false
        }
        if lhs.verificationPassed != rhs.verificationPassed {
            return false
        }
        if lhs.unifiedDiffPreview != rhs.unifiedDiffPreview {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(taskId)
        hasher.combine(prompt)
        hasher.combine(state)
        hasher.combine(verificationPassed)
        hasher.combine(unifiedDiffPreview)
    }
}


