/**
 * Cursor movement directions exposed across FFI.
 */

public enum CursorDirection {
    
    case up
    case down
    case left
    case right
    case lineStart
    case lineEnd
    case documentStart
    case documentEnd
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCursorDirection: FfiConverterRustBuffer {
    typealias SwiftType = CursorDirection

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CursorDirection {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .up
        
        case 2: return .down
        
        case 3: return .left
        
        case 4: return .right
        
        case 5: return .lineStart
        
        case 6: return .lineEnd
        
        case 7: return .documentStart
        
        case 8: return .documentEnd
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CursorDirection, into buf: inout [UInt8]) {
        switch value {
        
        
        case .up:
            writeInt(&buf, Int32(1))
        
        
        case .down:
            writeInt(&buf, Int32(2))
        
        
        case .left:
            writeInt(&buf, Int32(3))
        
        
        case .right:
            writeInt(&buf, Int32(4))
        
        
        case .lineStart:
            writeInt(&buf, Int32(5))
        
        
        case .lineEnd:
            writeInt(&buf, Int32(6))
        
        
        case .documentStart:
            writeInt(&buf, Int32(7))
        
        
        case .documentEnd:
            writeInt(&buf, Int32(8))
        
        }
    }
}


